import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse(`{"title":"UXD-034 — The Worlds: an orbiter's panel has a DETAIL tab (\\"The spacecraft\\"); \\"Stand here\\" opens on the photograph","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-034-worlds-orbiter-detail-tab-and-panorama-opening.md","filePath":"uxs/decisions/UXD-034-worlds-orbiter-detail-tab-and-panorama-opening.md"}`),r={name:"uxs/decisions/UXD-034-worlds-orbiter-detail-tab-and-panorama-opening.md"};function s(d,e,i,h,c,l){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="uxd-034-—-the-worlds-an-orbiter-s-panel-has-a-detail-tab-the-spacecraft-stand-here-opens-on-the-photograph" tabindex="-1">UXD-034 — The Worlds: an orbiter&#39;s panel has a DETAIL tab (&quot;The spacecraft&quot;); &quot;Stand here&quot; opens on the photograph <a class="header-anchor" href="#uxd-034-—-the-worlds-an-orbiter-s-panel-has-a-detail-tab-the-spacecraft-stand-here-opens-on-the-photograph" aria-label="Permalink to &quot;UXD-034 — The Worlds: an orbiter&#39;s panel has a DETAIL tab (&quot;The spacecraft&quot;); &quot;Stand here&quot; opens on the photograph&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by unit tests, e2e on three projects and screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed 2026-11-13, decided and built)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the recommendations of <code>docs/wip/2026-11-13-slice-D2-brief.md</code> §12 approved as written (&quot;Ok with all 12&quot;: D-decisions 4a, 5a, 6a, 7a); &quot;don&#39;t touch heroes ... what we have now is good&quot; (2026-11-14)</li><li><strong>Answers</strong>: WM1 and W6 of the UX feedback plan; slice D2 (W6 is the point <a href="./UXD-007-panorama-opens-facing-the-photo">UXD-007</a> decided; this record is its build and audit)</li><li><strong>Builds on</strong>: <a href="./UXD-007-panorama-opens-facing-the-photo">UXD-007</a>, <a href="./UXD-018-panel-shell-and-actions">UXD-018</a> (the panel order, the hero below the action row), <a href="./UXD-030-worlds-selected-orbiter-stays-visible-and-framed">UXD-030</a> (a selected orbiter stays visible beside its panel)</li><li><strong>Changes</strong>: <code>src/lib/surface-map/build-panel-tabs.ts</code> and <code>panel-tabs.ts</code> (<code>kind</code>, <code>details</code>), <code>src/lib/surface-scene/site-anatomy.ts</code> (orbiter rule), <code>SiteLandingPanel.svelte</code> (<code>heading</code>), <code>SurfaceScene.svelte</code> (DETAIL body; <code>enterPanorama</code> ends a running fly-in), <code>EarthObjectPanel.svelte</code> (DETAIL tab), <code>src/types/earth-object.ts</code> (<code>fleet_refs</code>), <code>src/types/surface-site.ts</code> (<code>photo_span_deg</code>), <code>PanoramaCompassRose.svelte</code> (<code>data-yaw</code>), <code>static/data/surface-hotspots.json</code>, <code>messages/*.json</code> (one key), tests listed in Verification</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><strong>WM1.</strong> All 19 Moon and Mars orbiters have a story file that is <code>null</code>, yet twelve of them showed a tab called STORY (the craft&#39;s cutaway was found by <code>siteAnatomy</code>) and drew the cutaway under &quot;On the surface&quot;, for a craft that never touched a surface. Five more had a drawing the panel hid: two because the <code>STAYED_IN_ORBIT</code> filter (which keeps an orbiter out of a <em>lander&#39;s</em> panel) also dropped the orbiter&#39;s own site (Mars 3 orbiter, Viking 1 orbiter), three because the site row has no <code>fleet_refs</code> (Clementine, MAVEN, Hope). Earth&#39;s panel showed no drawing at all.</p><p><strong>W6.</strong> The panorama opens at <code>entry_yaw_deg</code> (0 when absent). The brief counted 13 of 30 panoramas with one. The audit below read all 30 first frames.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Orbiters get a DETAIL tab (decision 4a).</strong> <code>buildSurfacePanelTabs({ kind: &#39;orbiter&#39; })</code> swaps STORY for DETAIL (<code>panel_tab_detail</code>, the existing key; DETAILS in de) and shows it when the site has a drawing. STORY comes back beside it only if an orbiter ever gets a story (<code>orbiter-detail.data.test.ts</code> names the orbiter that does). Landers keep STORY and &quot;On the surface&quot;.</li><li><strong>The heading is &quot;The spacecraft&quot;</strong> (<code>site_spacecraft_heading</code>, the one new key, 14 locales by hand from the glossary&#39;s spacecraft forms already used for <code>fly_opening_role_spacecraft</code>). The DETAIL body is the craft&#39;s drawing, its exploded cutaway when it has one, and the fleet link, as the STORY body drew them; no landing sheet (no orbiter has one).</li><li><strong>The 9 Earth objects with a drawing get the same tab (decision 5a)</strong> (ISS, Tiangong, Hubble, Chandra, XMM-Newton, Clementine, Chang&#39;e 2, JWST, Gaia: the objects whose <code>fleet_refs</code> name a drawn craft). The Earth-object data already carried <code>fleet_refs</code>; the type now says so.</li><li><strong>Orbiters show their own drawing (decision 6a).</strong> <code>siteAnatomy</code> skips the lander filter when the site&#39;s <code>kind</code> is <code>orbiter</code>, and falls back to the site id when the row has no <code>fleet_refs</code>: Mars 3 orbiter, Viking 1 orbiter, Clementine, MAVEN and Hope gain a DETAIL tab; TGO and Tianwen-1 orbiter have no drawing and no tab. 17 of 19 orbiters have it. No data row and no image added.</li><li><strong>The photo stays first, below the action row (decision 7a).</strong> Header, action row, hero (the first gallery image), tabs, body, unchanged; the guard test <code>surface-panel-order.spec.ts</code> asserts the hero precedes the tab row on every Moon and Mars site that has a gallery. Venus got its site galleries in slice D3 (<a href="./UXD-036-venus-galleries-use-the-worlds-ladder">UXD-036</a>), so the guard judges its three sites too.</li><li><strong>No hero image, hero slot or gallery order is changed</strong> (operator, 2026-11-14).</li><li><strong>&quot;Stand here&quot; opens on the photograph, and the audit.</strong> A new <code>panorama_metadata.photo_span_deg: [from, to]</code> (yaw degrees, increasing, wrapping through 0 when from &gt; to) names where the photograph sits on the 18 panoramas that have a horizontal gap; the 12 full-width ones have none. <code>panorama-entry.data.test.ts</code> checks that the opening yaw (<code>entry_yaw_deg</code>, else 0) is inside the span and clear of its edge by min(35°, 40 % of the span) (the view is 70° wide; a 50° photograph can only be centred), that every <code>unphotographed</code> wedge already in the data has a matching span, and that the list of 18 is the audited list.</li></ol><h3 id="audit-of-the-30-panoramas" tabindex="-1">Audit of the 30 panoramas <a class="header-anchor" href="#audit-of-the-30-panoramas" aria-label="Permalink to &quot;Audit of the 30 panoramas&quot;">​</a></h3><p>Method: a contact sheet of all 30 first frames with the opening yaw drawn (a 70° box), read by eye; the horizontal span read from the data&#39;s own <code>unphotographed</code> wedge (12 sites) and, for the six Earth pads, from the vertical edges of the pasted photograph (found by column differences, checked by eye).</p><table tabindex="0"><thead><tr><th>Result</th><th>Sites</th></tr></thead><tbody><tr><td>Full-width band, no span (12): any yaw is on the photograph; apollo12, 14, 15 and opportunity have a hand-set &quot;best view&quot; yaw, the rest open at 0. The vertical partials among them (apollo11, curiosity, perseverance, change4) have pitch 0 inside the band</td><td>apollo11, apollo12, apollo14, apollo15, curiosity, perseverance, phoenix, spirit, mars-pathfinder, opportunity, change3, change4</td></tr><tr><td>Partial, yaw already inside the photograph, clear of the edge (9)</td><td>apollo16, apollo17, luna9, luna17, change5, change6, zhurong, chandrayaan3, slim (hand-set yaws, centred)</td></tr><tr><td>Partial, a narrow wedge, yaw 0 inside the photograph (2)</td><td>viking1-lander 287.5..270, viking2-lander 300..270</td></tr><tr><td>Earth pads, partial, yaw 0 inside the photograph (6)</td><td>baikonur-1-5 295..65, baikonur-31-6 260..100, jiuquan-slc-43 285..75, sriharikota-slp 285..75, vandenberg-slc-4e 304..55, wenchang-lc-101 265..95</td></tr><tr><td><strong>Fixed: Insight</strong> (1) opened 20° from the end of its photograph, so a third of the view was the unphotographed wedge</td><td><code>entry_yaw_deg: 160</code>, on the lander deck (photograph 340..270)</td></tr></tbody></table><p><code>panorama-entry-yaw.mjs</code> was not re-run with <code>--write</code>: it reports apollo12, apollo14, apollo15, opportunity, zhurong and slim as &quot;full&quot; (the gap graticule is texture) and would delete their hand-set yaws.</p><h3 id="a-second-cause-found-by-the-e2e-the-fly-in" tabindex="-1">A second cause found by the e2e: the fly-in <a class="header-anchor" href="#a-second-cause-found-by-the-e2e-the-fly-in" aria-label="Permalink to &quot;A second cause found by the e2e: the fly-in&quot;">​</a></h3><p>The e2e on the camera the user gets failed for baikonur-1-5 (opened at yaw 180, not 0), wenchang (207) and change6 (296, not 176), on the first run, with the data right. <code>enterPanorama</code> set <code>camT</code> and <code>camP</code>, but a fly-in still running from selecting the site (about 1.5 s) overwrote them every frame, so the panorama opened on the globe&#39;s longitude when &quot;Stand here&quot; was pressed soon after the site was selected. <code>enterPanorama</code> now ends the fly-in (<code>flyActive = false</code>). After the fix the same three pass.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>One new key in 14 locales (<code>site_spacecraft_heading</code>); its hash is in <code>en-source-hashes.json</code>. <code>programs_on_surface</code> stays (landers, <code>/programs/&lt;id&gt;</code>).</li><li>Orbiter and Earth-object panels have a <code>data-testid=&quot;panel-tab-details&quot;</code> tab; <code>PanoramaCompassRose</code> carries <code>data-yaw</code> (the rounded camera yaw), which the e2e reads.</li><li><code>panorama-entry-yaw.mjs</code> is unchanged; <code>photo_span_deg</code> is set by hand (the <code>unphotographed</code> wedge, or the pasted photograph&#39;s edges) and the data test holds the two together.</li><li>Not done: the vertical position of every photograph against the horizon is checked by eye only (the Earth pads and the Moon bands include pitch 0); a panorama set with a different photo span per entry would open at the first entry&#39;s yaw (no site has a set).</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit: <code>build-panel-tabs.test.ts</code> (orbiter DETAIL, STORY back with a story, landers unchanged), <code>site-anatomy.test.ts</code> (orbiter rule, id fallback, lander filter kept), <code>orbiter-detail.data.test.ts</code> (19 orbiters, none has a story, the 5 hidden drawings shown, TGO and Tianwen-1 without), <code>panorama-entry.data.test.ts</code> (spans, wedge agreement, Insight red at yaw 0 and green at 160). E2E on desktop-chromium, mobile-chromium and mobile-landscape-chromium: <code>surface-orbiter-details.spec.ts</code> (8 orbiters, TGO, 2 landers, Hubble and ISS), <code>panorama-entry.spec.ts</code> (the 18 partial panoramas and a <code>?yaw=</code> deep link that still wins), <code>surface-panel-order.spec.ts</code> (hero before the tabs: Moon, Mars; Venus armed), <code>a11y-orbiter-details.spec.ts</code> (DETAIL open in en, ar, ru: 0 critical or serious). Screenshots read at 1440 x 900 and 390 x 844: LRO, MRO and MAVEN DETAIL, Apollo 11 STORY, Hubble DETAIL, &quot;Stand here&quot; at Insight and Baikonur 1/5. Not run: a real device, Firefox and WebKit, <code>preflight:coverage</code>.</p>',17)])])}const g=a(r,[["render",s]]);export{u as __pageData,g as default};
